# Knight's Tour Generator for 8x8 chessboard with custom encoding
# Encoding: '1'=(-2,1), '2'=(-1,2), '3'=(1,2), '4'=(2,1), '5'=(2,-1), '6'=(1,-2), '7'=(-1,-2), '8'=(-2,-1)

BOARD_SIZE = 8
ENCODING = {
    1: (-2, 1),
    2: (-1, 2),
    3: (1, 2),
    4: (2, 1),
    5: (2, -1),
    6: (1, -2),
    7: (-1, -2),
    8: (-2, -1)
}
# Invert mapping for move to digit
delta2code = {v: str(k) for k,v in ENCODING.items()}

board = [[-1 for _ in range(BOARD_SIZE)] for _ in range(BOARD_SIZE)]

moves = list(ENCODING.values())

def is_valid(x, y):
    return 0 <= x < BOARD_SIZE and 0 <= y < BOARD_SIZE and board[y][x] == -1

def knight_tour(x, y, move_num, path):
    if move_num == BOARD_SIZE * BOARD_SIZE:
        return True
    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        if is_valid(nx, ny):
            board[ny][nx] = move_num
            path.append((dx, dy))
            if knight_tour(nx, ny, move_num+1, path):
                return True
            path.pop()
            board[ny][nx] = -1
    return False

def main():
    x, y = 0, 0
    board[y][x] = 0
    path = []
    if knight_tour(x, y, 1, path):
        output = ''.join(delta2code[move] for move in path)
        print(output)
    else:
        print("No tour found!")

if __name__ == "__main__":
    main()
